package com.nextaicommerce.platform.fba;
import static org.assertj.core.api.Assertions.*;import java.util.*;import java.math.BigDecimal;import org.junit.jupiter.api.Test;import tools.jackson.databind.ObjectMapper;
class FbaShipmentParentsTest {
 ObjectMapper json=new ObjectMapper();UUID tenant=UUID.randomUUID(),store=UUID.randomUUID(),plan=UUID.randomUUID(),warehouse=UUID.randomUUID();
 FbaShipmentParents.Plan plan(String parent,boolean success,boolean history){var checkpoint=json.createObjectNode();var snapshot=json.createObjectNode();var origin=snapshot.putObject("origin");origin.put("warehouse",warehouse.toString()).put("amazonPlanId",parent);origin.putObject("scope").put("tenant",tenant.toString()).put("account",tenant.toString()).put("connection",store.toString()).put("replenishment",plan.toString());origin.putObject("attempts").putObject("request").put("operation","CREATE").put("status",success?"SUCCEEDED":"PENDING").put("amazonOperationId","verified-operation");origin.putObject("children").putObject("api-child").put("shipmentId","api-child").put("confirmationId","FBA-1");if(history)checkpoint.putObject("inboundOriginHistory").putArray(warehouse.toString()).add(snapshot);else checkpoint.putObject("inboundOrigins").set(warehouse.toString(),snapshot);return new FbaShipmentParents.Plan(plan,"User plan",checkpoint);}
 @Test void onlySuccessfulExactScopedRelationshipGroupsConfirmation(){var p=FbaShipmentParents.project(tenant,store,List.of(plan("amazon-plan",true,false)),Set.of("FBA-1"));assertThat(p.links().get("FBA-1").id()).isEqualTo("amazon-plan");assertThat(FbaShipmentParents.project(tenant,store,List.of(plan("amazon-plan",false,false)),Set.of("FBA-1")).links()).isEmpty();assertThat(FbaShipmentParents.project(UUID.randomUUID(),store,List.of(plan("amazon-plan",true,false)),Set.of("FBA-1")).links()).isEmpty();}
 @Test void preservedHistoryIsValidAndNeverUsesZipOrSkuGuess(){assertThat(FbaShipmentParents.project(tenant,store,List.of(plan("amazon-plan",true,true)),Set.of("FBA-1","UNRELATED")).links()).containsOnlyKeys("FBA-1");}
 @Test void dualImportedReferencesStayStandalone(){var p=FbaShipmentParents.project(tenant,store,List.of(plan("amazon-plan",true,false)),Set.of("FBA-1","api-child"));assertThat(p.links()).isEmpty();assertThat(p.ambiguous()).containsExactlyInAnyOrder("FBA-1","api-child");}
 @Test void conflictingParentHistoryDoesNotInventAParent(){var p=FbaShipmentParents.project(tenant,store,List.of(plan("old",true,true),plan("new",true,false)),Set.of("FBA-1"));assertThat(p.links()).isEmpty();assertThat(p.ambiguous()).contains("FBA-1");}
 @Test void packSkuQuantityConvertsToProductEachBeforeCases(){var c=FbaShipmentParents.cases(3,new BigDecimal("4"),new BigDecimal("5"));assertThat(c.each()).isEqualTo(12);assertThat(c.cases()).isEqualTo(2);assertThat(c.remainder()).isEqualTo(2);}
 @Test void unknownOrFractionalCaseUnitsAreNeverRounded(){assertThat(FbaShipmentParents.cases(3,BigDecimal.ONE,null).cases()).isNull();assertThat(FbaShipmentParents.cases(3,new BigDecimal("1.5"),BigDecimal.TEN).each()).isNull();assertThat(FbaShipmentParents.cases(3,BigDecimal.ONE,new BigDecimal("2.5")).cases()).isNull();}
 tools.jackson.databind.node.ObjectNode evidence(){String parent="wf11111111-1111-1111-1111-111111111111",child="sh11111111-1111-1111-1111-111111111111";var d=json.createObjectNode().put("tenant",tenant.toString()).put("store",store.toString()).put("marketplace","US").put("listingRequestId","list-read").put("completedAt","2026-11-18T23:00:00Z");var summary=d.putObject("listing").putArray("inboundPlans").addObject().put("inboundPlanId",parent);summary.putArray("marketplaceIds").add("US");var e=d.putArray("plans").addObject().put("planRequestId","detail-read");var body=e.putObject("plan").put("inboundPlanId",parent).put("name","User plan").put("status","SHIPPED");body.putArray("marketplaceIds").add("US");body.putArray("shipments").addObject().put("shipmentId",child);e.putArray("children").addObject().put("requestId","child-read").putObject("shipment").put("shipmentId",child).put("shipmentConfirmationId","FBA-1");return d;}
 @Test void directShippedApiEvidenceRequiresExactScopeAndCompleteChildren(){var doc=evidence();assertThat(FbaShipmentParents.projectDocuments(tenant,store,"US",List.of(doc),Set.of("FBA-1")).links()).containsKey("FBA-1");assertThat(FbaShipmentParents.projectDocuments(tenant,store,"CA",List.of(doc),Set.of("FBA-1")).links()).isEmpty();assertThat(FbaShipmentParents.projectDocuments(UUID.randomUUID(),store,"US",List.of(doc),Set.of("FBA-1")).links()).isEmpty();((tools.jackson.databind.node.ArrayNode)doc.path("plans").get(0).path("children")).removeAll();assertThat(FbaShipmentParents.projectDocuments(tenant,store,"US",List.of(doc),Set.of("FBA-1")).links()).isEmpty();}
 @Test void apiEvidenceCannotBorrowUnlistedPlanOrConflictingIdentity(){var d=evidence();((tools.jackson.databind.node.ArrayNode)d.path("listing").path("inboundPlans")).removeAll();assertThat(FbaShipmentParents.projectDocuments(tenant,store,"US",List.of(d),Set.of("FBA-1")).links()).isEmpty();var first=new FbaShipmentParents.Projection(Map.of("FBA-1",new FbaShipmentParents.Parent("old","",plan,warehouse,"child")),Set.of());var second=FbaShipmentParents.projectDocuments(tenant,store,"US",List.of(evidence()),Set.of("FBA-1"));assertThat(FbaShipmentParents.merge(first,second).links()).isEmpty();assertThat(FbaShipmentParents.merge(first,second).ambiguous()).contains("FBA-1");}
 @Test void repeatedCompleteEvidenceRefreshIsIdempotent(){var first=evidence();var second=evidence();second.put("listingRequestId","fresh-listing").put("completedAt","2026-11-19T23:00:00Z");var projection=FbaShipmentParents.projectDocuments(tenant,store,"US",List.of(first,second),Set.of("FBA-1"));assertThat(projection.links()).containsOnlyKeys("FBA-1");assertThat(projection.ambiguous()).isEmpty();assertThat(FbaShipmentParents.projectDocuments(tenant,UUID.randomUUID(),"US",List.of(first),Set.of("FBA-1")).links()).isEmpty();}
 @Test void conflictingCompleteMembershipRevisionsRemainFailClosed(){var first=evidence();var second=evidence();var entry=(tools.jackson.databind.node.ObjectNode)second.path("plans").get(0);((tools.jackson.databind.node.ArrayNode)entry.path("plan").path("shipments")).addObject().put("shipmentId","sh22222222-2222-2222-2222-222222222222");((tools.jackson.databind.node.ArrayNode)entry.path("children")).addObject().put("requestId","second-child").putObject("shipment").put("shipmentId","sh22222222-2222-2222-2222-222222222222").put("shipmentConfirmationId","FBA-2");var projection=FbaShipmentParents.projectDocuments(tenant,store,"US",List.of(first,second),Set.of("FBA-1"));assertThat(projection.links()).isEmpty();assertThat(projection.ambiguous()).contains("FBA-1");}
 @Test void verifiedDestinationRequiresExactCenterAndCannotReplaceShipFromOrBorrowScope(){
  var old=evidence();var d=evidence();var child=(tools.jackson.databind.node.ObjectNode)d.path("plans").get(0).path("children").get(0).path("shipment");child.put("destinationEvidenceVersion",1);var destination=child.putObject("destination").put("destinationType","AMAZON_WAREHOUSE").put("warehouseId","DFW6");destination.putObject("address").put("stateOrProvinceCode","TX").put("postalCode","75001").put("countryCode","US");
  var projected=FbaShipmentParents.projectDocuments(tenant,store,"US",List.of(old,d),Set.of("FBA-1")).links().get("FBA-1");
  assertThat(projected.destination().forCenter("DFW6")).isEqualTo("TX · 75001");assertThat(projected.destination().forCenter("SCK8")).isEmpty();assertThat(projected.postal()).isNull();
  assertThat(FbaShipmentParents.projectDocuments(tenant,UUID.randomUUID(),"US",List.of(d),Set.of("FBA-1")).links()).isEmpty();
  ((tools.jackson.databind.node.ObjectNode)destination.path("address")).put("postalCode","99999");
  assertThat(FbaShipmentParents.projectDocuments(tenant,store,"US",List.of(old,evidence(),d),Set.of("FBA-1")).links()).containsKey("FBA-1");
 }
 @Test void conflictingDestinationsKeepRelationshipButNeverShowWrongPostal(){var a=new FbaShipmentParents.Parent("P","",null,null,"C",null,null,null,Set.of("C"),"r",new FbaShipmentParents.Destination("DFW6","TX","75001","US"));var b=new FbaShipmentParents.Parent("P","",null,null,"C",null,null,null,Set.of("C"),"r2",new FbaShipmentParents.Destination("DFW6","TX","99999","US"));var merged=FbaShipmentParents.merge(new FbaShipmentParents.Projection(Map.of("FBA-1",a),Set.of()),new FbaShipmentParents.Projection(Map.of("FBA-1",b),Set.of()));assertThat(merged.links().get("FBA-1").destination().forCenter("DFW6")).isEmpty();assertThat(merged.ambiguous()).isEmpty();}
 @Test void checkedMissingOrOptimizedDestinationSuppressesOlderAddressWhileLegacyUnreadDoesNot(){
  var positive=evidence();var body=(tools.jackson.databind.node.ObjectNode)positive.path("plans").get(0).path("children").get(0).path("shipment");body.put("destinationEvidenceVersion",1);body.putObject("destination").put("destinationType","AMAZON_WAREHOUSE").put("warehouseId","DFW6").putObject("address").put("stateOrProvinceCode","TX").put("postalCode","75001");
  assertThat(FbaShipmentParents.projectDocuments(tenant,store,"US",List.of(positive,evidence()),Set.of("FBA-1")).links().get("FBA-1").destination().forCenter("DFW6")).isEqualTo("TX · 75001");
  for(boolean optimized:List.of(false,true)){var negative=evidence();var missing=(tools.jackson.databind.node.ObjectNode)negative.path("plans").get(0).path("children").get(0).path("shipment");missing.put("destinationEvidenceVersion",1);if(optimized)missing.putObject("destination").put("destinationType","AMAZON_OPTIMIZED");var result=FbaShipmentParents.projectDocuments(tenant,store,"US",List.of(positive,negative),Set.of("FBA-1"));assertThat(result.links()).containsKey("FBA-1");assertThat(result.links().get("FBA-1").destination().forCenter("DFW6")).isEmpty();}
 }
}
